const std = @import("std");

const HtrNode = struct {
    phase: f32,
    amplitude: f32,
    resonance: f32,
    topological_charge: i32,
    entanglement_factor: f32,
};

const TopologyMatrix = struct {
    data: []f32,
    rows: usize,
    cols: usize,
    allocator: std.mem.Allocator,

    fn init(allocator: std.mem.Allocator, rows: usize, cols: usize) !TopologyMatrix {
        if (rows == 0 or cols == 0) return error.InvalidDimensions;

        const element_count = try std.math.mul(usize, rows, cols);
        const data = try allocator.alloc(f32, element_count);
        @memset(data, 0.0);

        return .{
            .data = data,
            .rows = rows,
            .cols = cols,
            .allocator = allocator,
        };
    }

    fn deinit(self: *TopologyMatrix) void {
        self.allocator.free(self.data);
        self.data = &[_]f32{};
        self.rows = 0;
        self.cols = 0;
    }

    fn get(self: *const TopologyMatrix, row: usize, col: usize) f32 {
        std.debug.assert(row < self.rows);
        std.debug.assert(col < self.cols);
        return self.data[row * self.cols + col];
    }

    fn set(self: *TopologyMatrix, row: usize, col: usize, value: f32) void {
        std.debug.assert(row < self.rows);
        std.debug.assert(col < self.cols);
        self.data[row * self.cols + col] = value;
    }
};

const HtrState = struct {
    nodes: []HtrNode,
    previous_resonances: []f32,
    next_resonances: []f32,
    weights: TopologyMatrix,
    allocator: std.mem.Allocator,

    fn init(allocator: std.mem.Allocator, dimension: usize) !HtrState {
        if (dimension == 0) return error.InvalidDimensions;

        const nodes = try allocator.alloc(HtrNode, dimension);
        errdefer allocator.free(nodes);

        const previous_resonances = try allocator.alloc(f32, dimension);
        errdefer allocator.free(previous_resonances);

        const next_resonances = try allocator.alloc(f32, dimension);
        errdefer allocator.free(next_resonances);

        const dimension_f32: f32 = @floatFromInt(dimension);

        for (nodes, 0..) |*node, index| {
            const index_f32: f32 = @floatFromInt(index);
            node.* = .{
                .phase = (index_f32 / dimension_f32) * (2.0 * std.math.pi),
                .amplitude = 1.0,
                .resonance = 0.0,
                .topological_charge = @as(i32, @intCast(index % 3)) - 1,
                .entanglement_factor = 0.5,
            };
            previous_resonances[index] = 0.0;
            next_resonances[index] = 0.0;
        }

        var weights = try TopologyMatrix.init(allocator, dimension, dimension);
        errdefer weights.deinit();

        for (0..dimension) |row| {
            for (0..dimension) |col| {
                const row_f32: f32 = @floatFromInt(row);
                const col_f32: f32 = @floatFromInt(col);
                const distance = @abs(row_f32 - col_f32);
                weights.set(row, col, @exp(-distance * 0.1));
            }
        }

        return .{
            .nodes = nodes,
            .previous_resonances = previous_resonances,
            .next_resonances = next_resonances,
            .weights = weights,
            .allocator = allocator,
        };
    }

    fn deinit(self: *HtrState) void {
        self.allocator.free(self.nodes);
        self.allocator.free(self.previous_resonances);
        self.allocator.free(self.next_resonances);
        self.nodes = &[_]HtrNode{};
        self.previous_resonances = &[_]f32{};
        self.next_resonances = &[_]f32{};
        self.weights.deinit();
    }

    fn normalizePhase(value: f32) f32 {
        const period = 2.0 * std.math.pi;
        const remainder = @rem(value, period);
        return if (remainder < 0.0) remainder + period else remainder;
    }

    fn clampFinite(value: f32, minimum: f32, maximum: f32) f32 {
        if (!std.math.isFinite(value)) return minimum;
        return @max(minimum, @min(maximum, value));
    }

    fn forward(self: *HtrState, input: []const f32, output: []f32) !void {
        if (input.len > self.nodes.len or output.len < input.len) return error.InvalidBufferLength;

        for (self.nodes, 0..) |node, index| {
            self.previous_resonances[index] = if (std.math.isFinite(node.resonance)) node.resonance else 0.0;
        }

        for (self.nodes, 0..) |*node, index| {
            var state_update: f32 = 0.0;

            for (self.previous_resonances, 0..) |resonance, other_index| {
                if (other_index != index) {
                    state_update += self.weights.get(index, other_index) * resonance;
                }
            }

            const raw_input_value: f32 = if (index < input.len) input[index] else 0.0;
            const input_value: f32 = if (std.math.isFinite(raw_input_value)) raw_input_value else 0.0;
            const safe_state_update: f32 = if (std.math.isFinite(state_update)) state_update else 0.0;
            const updated_phase = node.phase + input_value + safe_state_update * 0.01;
            const updated_amplitude = node.amplitude + @abs(input_value) * 0.001;
            const charge_f32: f32 = @floatFromInt(node.topological_charge);

            node.phase = normalizePhase(if (std.math.isFinite(updated_phase)) updated_phase else 0.0);
            node.amplitude = clampFinite(updated_amplitude, 0.0, 2.0);
            self.next_resonances[index] = node.amplitude * @sin(node.phase) * charge_f32;
        }

        for (self.nodes, 0..) |*node, index| {
            const resonance = if (std.math.isFinite(self.next_resonances[index])) self.next_resonances[index] else 0.0;
            node.resonance = resonance;
            self.previous_resonances[index] = resonance;

            if (index < output.len) {
                output[index] = resonance;
            }
        }
    }

    fn braidAnyons(self: *HtrState, index_a: usize, index_b: usize) !void {
        if (index_a >= self.nodes.len or index_b >= self.nodes.len) return error.InvalidNodeIndex;
        if (index_a == index_b) return;

        const node_a = &self.nodes[index_a];
        const node_b = &self.nodes[index_b];

        const original_phase_a = node_a.phase;
        node_a.phase = normalizePhase(node_b.phase + std.math.pi / 2.0);
        node_b.phase = normalizePhase(original_phase_a - std.math.pi / 2.0);
        node_a.entanglement_factor = clampFinite(node_a.entanglement_factor + 0.1, 0.0, 1.0);
        node_b.entanglement_factor = clampFinite(node_b.entanglement_factor + 0.1, 0.0, 1.0);
    }
};

const JaideCore = struct {
    state: HtrState,

    fn init(allocator: std.mem.Allocator, width: usize) !JaideCore {
        return .{
            .state = try HtrState.init(allocator, width),
        };
    }

    fn deinit(self: *JaideCore) void {
        self.state.deinit();
    }

    fn processTokenStream(self: *JaideCore, stream: []const f32, output_stream: []f32) !void {
        if (stream.len != output_stream.len) return error.InvalidBufferLength;
        if (self.state.nodes.len == 0) return error.InvalidDimensions;

        const width = self.state.nodes.len;
        var start: usize = 0;

        while (start < stream.len) {
            const end = @min(start + width, stream.len);
            const input_chunk = stream[start..end];
            const output_chunk = output_stream[start..end];

            if (width >= 2 and input_chunk.len >= 2) {
                try self.state.braidAnyons(input_chunk.len - 1, input_chunk.len - 2);
            }

            try self.state.forward(input_chunk, output_chunk);

            start = end;
        }
    }
};

pub fn main() !void {
    var general_purpose_allocator = std.heap.GeneralPurposeAllocator(.{}){};
    defer {
        const status = general_purpose_allocator.deinit();
        std.debug.assert(status == .ok);
    }

    const allocator = general_purpose_allocator.allocator();
    const width: usize = 4096;
    const sequence_length: usize = 8192;

    var jaide = try JaideCore.init(allocator, width);
    defer jaide.deinit();

    var input = try allocator.alloc(f32, sequence_length);
    defer allocator.free(input);

    var output = try allocator.alloc(f32, sequence_length);
    defer allocator.free(output);

    for (input, 0..) |*value, index| {
        const token: f32 = @floatFromInt(index % 256);
        value.* = token / 255.0;
    }

    try jaide.processTokenStream(input, output);

    var checksum: f64 = 0.0;
    for (output) |value| {
        checksum += @as(f64, value);
    }

    const stdout = std.io.getStdOut().writer();
    try stdout.print("{d:.8}\n", .{checksum});
}
